        "gender": "female"
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Condition/condition-1",
      "resource": {
        "resourceType": "Condition",
        "id": "condition-1",
        "subject": {
          "reference": "Patient/patient-1"
        },
        "code": {
          "text": "Non-cystic fibrosis bronchiectasis"
        },
        "clinicalStatus": {
          "coding": [
            {
              "system": "http://terminology.hl7.org/CodeSystem/condition-clinical",
              "code": "active"
            }
          ]
        },
        "onsetString": "Diagnosed by HRCT approximately 5 years ago",
        "bodySite": [
          {
            "text": "Right lower lobe"
          },
          {
            "text": "Lingula"
          }
        ],
        "note": [
          {
            "text": "Idiopathic bronchiectasis following recurrent pneumonias in her 50s. Previously managed by respiratory clinic; now GP-led care."
          },
          {
            "text": "Clinically stable. Persistent coarse bibasal crackles are consistent with known structural disease and baseline airway distortion with mucus plugging rather than a new parenchymal process. No current evidence of acute exacerbation."
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Condition/condition-2",
      "resource": {
        "resourceType": "Condition",
        "id": "condition-2",
        "subject": {
          "reference": "Patient/patient-1"
        },
        "code": {
          "text": "Anxiety concerning bronchiectasis progression and auscultatory findings"
        },
        "clinicalStatus": {
          "coding": [
            {
              "system": "http://terminology.hl7.org/CodeSystem/condition-clinical",
              "code": "active"
            }
          ]
        }
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Condition/condition-3",
      "resource": {
        "resourceType": "Condition",
        "id": "condition-3",
        "subject": {
          "reference": "Patient/patient-1"
        },
        "code": {
          "text": "History of recurrent pneumonias"
        },
        "onsetString": "In her 50s",
        "note": [
          {
            "text": "Historical recurrent pneumonias preceded bronchiectasis."
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-1",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-1",
        "status": "final",
        "code": {
          "text": "Reported respiratory symptom stability"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Feels pretty much the same as usual. No increase in cough or shortness of breath, and no change in exercise tolerance."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-2",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-2",
        "status": "final",
        "code": {
          "text": "Chronic productive cough"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Chronic morning productive cough with unchanged pattern: same cupful of sputum, then settles."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-3",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-3",
        "status": "final",
        "code": {
          "text": "Sputum characteristics"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Yellow at baseline; no increase in volume, thickness or purulence; no smell."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-4",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-4",
        "status": "final",
        "code": {
          "text": "Exercise tolerance and activity"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Exercise tolerance unchanged. Walks dog for 20–30 minutes most days, slower uphill."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-5",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-5",
        "status": "final",
        "code": {
          "text": "Systemic and chest symptoms"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "No fever, chills, night sweats or chest pain. No increased fatigue identified in the assessment."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-6",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-6",
        "status": "final",
        "code": {
          "text": "Haemoptysis"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "No haemoptysis for months; no active haemoptysis."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-7",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-7",
        "status": "final",
        "code": {
          "text": "Recent antibiotic treatment and hospitalisation"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "No antibiotics or hospitalisation in the last 6–9 months."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-8",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-8",
        "status": "final",
        "code": {
          "text": "Wheeze history"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Occasional cold-weather wheeze; reliever salbutamol MDI used only 1–2 times per month."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-9",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-9",
        "status": "final",
        "code": {
          "text": "Cardiorespiratory and constitutional red-flag symptoms"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "No orthopnoea, paroxysmal nocturnal dyspnoea, ankle swelling or weight loss. Appetite okay."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-10",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-10",
        "status": "final",
        "code": {
          "text": "Bronchiectasis exacerbation history"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Usually 1–2 infective exacerbations per year treated with oral antibiotics; none so far this year."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-11",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-11",
        "status": "final",
        "code": {
          "text": "Previous bronchiectasis screening results"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Previous immunological, cystic fibrosis and allergic bronchopulmonary aspergillosis screens reported as normal.",
        "note": [
          {
            "text": "Background information from old respiratory letters, EMR and patient."
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-12",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-12",
        "status": "final",
        "code": {
          "text": "Smoking and passive smoke exposure"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Never smoker; no passive smoke exposure."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-13",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-13",
        "status": "final",
        "code": {
          "text": "Social and functional status"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Retired administrator. Lives with husband and is independent in activities of daily living."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-14",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-14",
        "status": "final",
        "code": {
          "text": "Home environmental exposure"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Older home with some bathroom mould, cleaned regularly. Patient asks whether cold damp weather or bathroom mould is making her lungs rattlier; contribution is uncertain and assessed as likely minor in otherwise stable disease."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-15",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-15",
        "status": "final",
        "code": {
          "text": "Patient concerns about respiratory disease"
